parameters.jsCode:
const contactoId = $('Worker Comercial').first().json.contacto_record_id;
const empresaId = $('Worker Comercial').first().json.empresa_record_id;

const cotizaciones = $input.all()
  .filter(item => {
    const campos = item.json.fields ?? {};

    return (
      (campos.Contacto ?? []).includes(contactoId) &&
      (campos.Empresa ?? []).includes(empresaId)
    );
  })
  .map(item => ({
    cotizacion_id: item.json.fields.Cotizacion_ID,
    estado: item.json.fields.Estado ?? 'Sin estado',
    solicitud_id: item.json.fields.Solicitud_ID ?? ''
  }));

return [{
  json: {
    exito: true,
    accion: 'consultar',
    cantidad: cotizaciones.length,
    cotizaciones
  }
}];
